struct Pool {
    vector<Node> store;
    deque<int> freeIdx;
    int alloc(int v){
        if (freeIdx.empty()){ store.emplace_back(v); return store.size()-1; }
        int i = freeIdx.back(); freeIdx.pop_back();
        store[i].val = v; return i;
    }
    void release(int i){ freeIdx.push_back(i); }
};
// indices-as-pointers: zero new/delete in hot loop, contiguous-ish storage bonus
